=== FILE: apb_regs.v ===
`timescale 1ns / 1ps
`default_nettype none

// apb_regs: four 32-bit read/write registers behind an APB4 subordinate port.
// Implements microarchitecture.md (zero wait states, no state machine,
// PSLVERR for unmapped addresses, synchronous active-low reset).
module apb_regs #(
    parameter ADDR_WIDTH = 8,
    parameter DATA_WIDTH = 32
) (
    input  wire                    pclk,
    input  wire                    presetn,
    input  wire [ADDR_WIDTH-1:0]   paddr,
    input  wire                    psel,
    input  wire                    penable,
    input  wire                    pwrite,
    input  wire [DATA_WIDTH-1:0]   pwdata,
    input  wire [DATA_WIDTH/8-1:0] pstrb,
    output wire [DATA_WIDTH-1:0]   prdata,
    output wire                    pready,
    output wire                    pslverr
);

    localparam STRB_WIDTH = DATA_WIDTH / 8;

    // The only state: four registers as separate flops.
    reg [DATA_WIDTH-1:0] reg0;
    reg [DATA_WIDTH-1:0] reg1;
    reg [DATA_WIDTH-1:0] reg2;
    reg [DATA_WIDTH-1:0] reg3;

    // Access phase: the one cycle in which the response is sampled and a
    // write takes effect.
    wire access = psel & penable;

    // Mapped: word aligned and inside 0x0..0xC.
    wire mapped = (paddr[1:0] == 2'b00) &&
                  (paddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});

    wire [1:0] idx = paddr[3:2];

    wire wr_en = access & pwrite & mapped;
    wire rd_en = access & ~pwrite & mapped;

    // Byte enables expanded to a bit mask.
    wire [DATA_WIDTH-1:0] wmask;
    genvar g;
    generate
        for (g = 0; g < STRB_WIDTH; g = g + 1) begin : g_wmask
            assign wmask[8*g +: 8] = {8{pstrb[g]}};
        end
    endgenerate

    // merge(old, data, strb): strobed bytes from pwdata, others kept.
    wire [DATA_WIDTH-1:0] reg0_next = (reg0 & ~wmask) | (pwdata & wmask);
    wire [DATA_WIDTH-1:0] reg1_next = (reg1 & ~wmask) | (pwdata & wmask);
    wire [DATA_WIDTH-1:0] reg2_next = (reg2 & ~wmask) | (pwdata & wmask);
    wire [DATA_WIDTH-1:0] reg3_next = (reg3 & ~wmask) | (pwdata & wmask);

    always @(posedge pclk) begin
        if (!presetn) begin
            reg0 <= {DATA_WIDTH{1'b0}};
            reg1 <= {DATA_WIDTH{1'b0}};
            reg2 <= {DATA_WIDTH{1'b0}};
            reg3 <= {DATA_WIDTH{1'b0}};
        end else begin
            if (wr_en && (idx == 2'd0)) reg0 <= reg0_next;
            if (wr_en && (idx == 2'd1)) reg1 <= reg1_next;
            if (wr_en && (idx == 2'd2)) reg2 <= reg2_next;
            if (wr_en && (idx == 2'd3)) reg3 <= reg3_next;
        end
    end

    // Combinational 4:1 read multiplexer.
    wire [DATA_WIDTH-1:0] rmux = (idx == 2'd0) ? reg0 :
                                 (idx == 2'd1) ? reg1 :
                                 (idx == 2'd2) ? reg2 :
                                                 reg3;

    assign prdata  = rd_en ? rmux : {DATA_WIDTH{1'b0}};
    assign pready  = 1'b1;
    assign pslverr = access & ~mapped;

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: apb_regs_tb.v ===
`timescale 1ns / 1ps
`default_nettype none

// Self-checking directed testbench for apb_regs.
// Inputs are driven just after the falling edge; outputs are sampled 1 ns
// later, well before the next rising edge, so there is no race with the DUT.
module apb_regs_tb;

    reg         pclk = 1'b0;
    reg         presetn;
    reg  [7:0]  paddr;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    wire [31:0] prdata;
    wire        pready;
    wire        pslverr;

    integer passed;
    integer failed;
    integer mon_passed = 0;
    integer mon_failed = 0;
    integer rc;
    reg [8*64-1:0] nonce;
    reg [7:0]      cur_addr;
    reg [31:0]     model [0:3];

    apb_regs #(
        .ADDR_WIDTH(8),
        .DATA_WIDTH(32)
    ) dut (
        .pclk    (pclk),
        .presetn (presetn),
        .paddr   (paddr),
        .psel    (psel),
        .penable (penable),
        .pwrite  (pwrite),
        .pwdata  (pwdata),
        .pstrb   (pstrb),
        .prdata  (prdata),
        .pready  (pready),
        .pslverr (pslverr)
    );

    always #5 pclk = ~pclk;

    // ------------------------------------------------------------------
    // Reference model, written independently of the design.
    // ------------------------------------------------------------------
    function tb_mapped;
        input [7:0] a;
        begin
            tb_mapped = (a[1:0] == 2'b00) && (a < 8'h10);
        end
    endfunction

    function [31:0] tb_merge;
        input [31:0] old;
        input [31:0] data;
        input [3:0]  strb;
        begin
            tb_merge = { (strb[3] ? data[31:24] : old[31:24]),
                         (strb[2] ? data[23:16] : old[23:16]),
                         (strb[1] ? data[15:8]  : old[15:8]),
                         (strb[0] ? data[7:0]   : old[7:0]) };
        end
    endfunction

    // ------------------------------------------------------------------
    // Check helpers: every failure goes through $error; passes are counted.
    // ------------------------------------------------------------------
    task chk;
        input          ok;
        input [8*64-1:0] what;
        begin
            if (ok === 1'b1) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("FAIL at %0t (addr %h): %0s", $time, cur_addr, what);
            end
        end
    endtask

    task chk32;
        input [31:0]     got;
        input [31:0]     exp;
        input [8*64-1:0] what;
        begin
            if (got === exp) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("FAIL at %0t (addr %h): %0s: got %h expected %h",
                       $time, cur_addr, what, got, exp);
            end
        end
    endtask

    // ------------------------------------------------------------------
    // Bus tasks
    // ------------------------------------------------------------------
    // Idle cycles: psel low, with junk on the other inputs (a mapped
    // address, write, full strobes) to show nothing is written unselected.
    task idle;
        input [7:0] n;
        begin
            repeat (n) begin
                @(negedge pclk);
                psel     = 1'b0;
                penable  = 1'b0;
                pwrite   = 1'b1;
                paddr    = 8'h04;
                pwdata   = 32'hDEAD_BEEF;
                pstrb    = 4'hF;
                cur_addr = 8'h04;
                #1;
                chk(pslverr === 1'b0, "idle: pslverr low");
                chk32(prdata, 32'h0, "idle: prdata zero");
                chk(pready === 1'b1, "idle: pready high");
            end
        end
    endtask

    task apb_write;
        input [7:0]  addr;
        input [31:0] data;
        input [3:0]  strb;
        reg          exp_err;
        begin
            exp_err  = ~tb_mapped(addr);
            cur_addr = addr;
            // setup phase
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = 1'b1;
            paddr   = addr;
            pwdata  = data;
            pstrb   = strb;
            #1;
            chk(pslverr === 1'b0, "write setup: pslverr low");
            chk32(prdata, 32'h0, "write setup: prdata zero");
            // access phase
            @(negedge pclk);
            penable = 1'b1;
            #1;
            chk(pready === 1'b1, "write access: pready high (zero wait)");
            chk(pslverr === exp_err, "write access: pslverr per address policy");
            chk32(prdata, 32'h0, "write access: prdata zero");
            if (!exp_err)
                model[addr[3:2]] = tb_merge(model[addr[3:2]], data, strb);
        end
    endtask

    task apb_read;
        input [7:0] addr;
        reg         exp_err;
        reg [31:0]  exp_data;
        begin
            exp_err  = ~tb_mapped(addr);
            exp_data = exp_err ? 32'h0 : model[addr[3:2]];
            cur_addr = addr;
            // setup phase
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = addr;
            pwdata  = 32'h0;
            pstrb   = 4'h0;
            #1;
            chk(pslverr === 1'b0, "read setup: pslverr low");
            chk32(prdata, 32'h0, "read setup: prdata zero");
            // access phase
            @(negedge pclk);
            penable = 1'b1;
            #1;
            chk(pready === 1'b1, "read access: pready high (zero wait)");
            chk(pslverr === exp_err, "read access: pslverr per address policy");
            chk32(prdata, exp_data, "read access: prdata");
        end
    endtask

    task check_all_regs;
        begin
            apb_read(8'h00);
            apb_read(8'h04);
            apb_read(8'h08);
            apb_read(8'h0C);
        end
    endtask

    task reset_dut;
        begin
            @(negedge pclk);
            psel     = 1'b0;
            penable  = 1'b0;
            pwrite   = 1'b0;
            pstrb    = 4'h0;
            presetn  = 1'b0;
            cur_addr = paddr;
            repeat (2) begin
                @(negedge pclk);
                #1;
                chk(pready === 1'b1, "reset: pready high");
                chk(pslverr === 1'b0, "reset: pslverr low");
                chk32(prdata, 32'h0, "reset: prdata zero");
            end
            @(negedge pclk);
            presetn  = 1'b1;
            model[0] = 32'h0;
            model[1] = 32'h0;
            model[2] = 32'h0;
            model[3] = 32'h0;
        end
    endtask

    // ------------------------------------------------------------------
    // Protocol monitor (design intent): pready always high; prdata and
    // pslverr zero outside the access phase. Inputs change only at the
    // falling edge, so sampling at the rising edge is race free.
    // ------------------------------------------------------------------
    always @(posedge pclk) begin
        if (pready === 1'b1) begin
            mon_passed = mon_passed + 1;
        end else begin
            mon_failed = mon_failed + 1;
            $error("MONITOR FAIL at %0t: pready not high", $time);
        end
        if (!(psel === 1'b1 && penable === 1'b1)) begin
            if (pslverr === 1'b0 && prdata === 32'h0) begin
                mon_passed = mon_passed + 1;
            end else begin
                mon_failed = mon_failed + 1;
                $error("MONITOR FAIL at %0t: response not quiet outside access (pslverr=%b prdata=%h)",
                       $time, pslverr, prdata);
            end
        end
    end

    // ------------------------------------------------------------------
    // Main sequence
    // ------------------------------------------------------------------
    initial begin
        passed   = 0;
        failed   = 0;
        nonce    = {64{8'h00}};
        cur_addr = 8'h00;
        rc = $value$plusargs("nirmaan_nonce=%s", nonce);

        presetn  = 1'b0;
        psel     = 1'b0;
        penable  = 1'b0;
        pwrite   = 1'b0;
        paddr    = 8'h00;
        pwdata   = 32'h0;
        pstrb    = 4'h0;
        model[0] = 32'h0;
        model[1] = 32'h0;
        model[2] = 32'h0;
        model[3] = 32'h0;

        // 1. Reset: outputs quiet, pready high.
        repeat (3) begin
            @(negedge pclk);
            #1;
            chk(pready === 1'b1, "reset: pready high");
            chk(pslverr === 1'b0, "reset: pslverr low");
            chk32(prdata, 32'h0, "reset: prdata zero");
        end
        @(negedge pclk);
        presetn = 1'b1;
        idle(8'd2);

        // 2. Reset values.
        check_all_regs;

        // 3. Write then read every register, full strobes.
        apb_write(8'h00, 32'hA5A5_0F0F, 4'hF);
        apb_write(8'h04, 32'h0123_4567, 4'hF);
        apb_write(8'h08, 32'h89AB_CDEF, 4'hF);
        apb_write(8'h0C, 32'hFEDC_BA98, 4'hF);
        idle(8'd1);
        check_all_regs;

        // 4. pstrb partial writes.
        apb_write(8'h00, 32'hDDCC_BBAA, 4'b0001); apb_read(8'h00);
        apb_write(8'h04, 32'h1122_3344, 4'b0010); apb_read(8'h04);
        apb_write(8'h08, 32'h5566_7788, 4'b0100); apb_read(8'h08);
        apb_write(8'h0C, 32'h99AA_BBCC, 4'b1000); apb_read(8'h0C);
        apb_write(8'h00, 32'hFFFF_FFFF, 4'b0110); apb_read(8'h00);
        apb_write(8'h04, 32'h0000_0000, 4'b1001); apb_read(8'h04);
        apb_write(8'h08, 32'hCAFE_F00D, 4'b0000); apb_read(8'h08); // no change, no error
        apb_write(8'h0C, 32'h1234_5678, 4'b0011); apb_read(8'h0C);
        check_all_regs;

        // 5. Back-to-back transfers, then idle gaps.
        apb_write(8'h04, 32'h0BAD_CAFE, 4'hF);
        apb_write(8'h08, 32'h600D_F00D, 4'hF);
        apb_read(8'h04);
        apb_read(8'h08);
        apb_write(8'h00, 32'h7777_8888, 4'hF);
        apb_read(8'h00);
        apb_write(8'h0C, 32'h4321_8765, 4'hF);
        apb_read(8'h0C);
        idle(8'd3);
        apb_read(8'h00);
        idle(8'd1);
        apb_write(8'h00, 32'h3C3C_C3C3, 4'hF);
        idle(8'd2);
        apb_read(8'h00);
        idle(8'd5);
        check_all_regs;

        // 6. PSLVERR policy: misaligned and out-of-range writes change nothing.
        apb_write(8'h01, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h02, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h03, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h05, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h0E, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h10, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h14, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h80, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'hFC, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'hFF, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h1C, 32'hFFFF_FFFF, 4'h0); // unmapped, empty strobes: still error
        check_all_regs;
        // Unmapped reads return zero with pslverr (0x14 and 0x5 alias REG1 if mis-decoded).
        apb_read(8'h01);
        apb_read(8'h02);
        apb_read(8'h03);
        apb_read(8'h05);
        apb_read(8'h0E);
        apb_read(8'h10);
        apb_read(8'h14);
        apb_read(8'h80);
        apb_read(8'hFC);
        apb_read(8'hFF);
        // Mapped transfer right after an error transfer.
        apb_read(8'h04);
        idle(8'd1);

        // 7. Reset again with nonzero registers.
        reset_dut;
        idle(8'd1);
        check_all_regs;
        apb_write(8'h0C, 32'hA1B2_C3D4, 4'hF);
        apb_read(8'h0C);
        idle(8'd2);

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed",
                 nonce, passed + mon_passed, failed + mon_failed);
        $finish;
    end

    // Watchdog: a hung run fails with a verdict instead of running forever.
    initial begin
        #200000;
        $error("TIMEOUT: testbench did not complete");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed",
                 nonce, passed + mon_passed, failed + mon_failed + 1);
        $finish;
    end

endmodule

`default_nettype wire
=== END FILE ===
